import {nl} from '@natlang/node';
type Root={files(pattern:string):Promise<{relativePath:string;readText():Promise<string>}[]>;file(path:string):{readText():Promise<string>;writeText(text:string):Promise<void>}};
export async function run(folder:Root):Promise<string>{const records=JSON.parse(await folder.file('records.json').readText());const selected:string[]=[];let total=0;for(let index=0;index<records.length;index++){const record=records[index];const text=await folder.file(record.note).readText();const yes=await nl<boolean>`Does the text contain any positive mention of urgent, including earlier or proposed states?`(text);if(yes){selected.push(record.id);total+=record.amount;}}await folder.file('report.json').writeText(JSON.stringify({selected:selected.sort(),total}));return 'done';}

