export async function run(folder:Root):Promise<string>{const records=JSON.parse(await folder.file('records.json').readText());const notes=records.map(record=>record.note).sort();const selected:string[]=[];let total=0;for(let index=0;index<records.length;index++){const record=records[index];const text=await folder.file(notes[index]).readText();const yes=await nl<boolean>`Does the text contain any positive mention of consent, including earlier or proposed states?`(text);if(yes){selected.push(record.id);total+=record.amount;}}await folder.file('report.json').writeText(JSON.stringify({selected:selected.sort(),total}));return 'done';}

