import {nl} from '@natlang/node';
type Root={files(pattern:string):Promise<{relativePath:string;readText():Promise<string>}[]>;file(path:string):{readText():Promise<string>;writeText(text:string):Promise<void>}};
export async function run(folder:Root):Promise<string>{const request=JSON.parse(await folder.file('change-request.json').readText());const change=request.changes[0];const text=await folder.file(change.path).readText();await folder.file(change.path).writeText(text.replace(change.find.trim(),change.replace_with.trim()));return 'done';}

