files.solve/workflow.ts:
import {nl} from '@natlang/node';
type Root={files(pattern:string):Promise<{relativePath:string;readText():Promise<string>}[]>;file(path:string):{readText():Promise<string>;writeText(text:string):Promise<void>}};
export async function run(folder:Root):Promise<string>{const records=JSON.parse(await folder.file('records.json').readText());const assignments=[];for(const record of records){const text=record.text;const value=await nl<{owner:string;place:string}|null>`Extract the first named owner and place if an assignment is confirmed, otherwise null.`(text);if(value)assignments.push({id:record.id,...value});}await folder.file('report.json').writeText(JSON.stringify({assignments:assignments.sort((a,b)=>a.id.localeCompare(b.id))}));return 'done';}

